INSERT INTO edumaps_items (id, type, title, category, tags, recommended_grades, description, lat, lng, image_url, external_url, sort) VALUES ('res_193', 'OFFLINE', '국채보상운동기념도서관', '중구', '["체험","관람","문화예술","역사"]', '[4,5,6]', '우리말 이야기와 대구의 역사문화를 체험하며 배우는 참여형 공간', 35.868464, 128.6016669, NULL, 'https://library.daegu.go.kr/gukbo/index.do', 82);
INSERT INTO edumaps_items (id, type, title, category, tags, recommended_grades, description, lat, lng, image_url, external_url, sort) VALUES ('res_194', 'OFFLINE', '달성공원', '중구', '["체험","관람","생태"]', '[1,2,3,4,5,6]', '대구에서 가장 오래된 도심공원으로 동물원도 운영. 공원 내 향토역사관 방문 가능', 35.874004, 128.5780991, NULL, 'https://tour.daegu.go.kr/index.do?menu_id=00002943&menu_link=/front/tour/tourMapsView.do?tourId=KOATTR_124', 83);
