INSERT INTO edumaps_items (id, type, title, category, tags, recommended_grades, description, lat, lng, image_url, external_url, sort) VALUES ('res_197', 'OFFLINE', '대구향교', '중구', '["체험","관람","문화예술"]', '[3,4,5,6]', '600년 역사의 대구향교에서 배우는 성현의 지혜와 선비정신', 35.859856, 128.596012, NULL, 'http://www.daeguhyanggyo.org/', 86);
INSERT INTO edumaps_items (id, type, title, category, tags, recommended_grades, description, lat, lng, image_url, external_url, sort) VALUES ('res_198', 'OFFLINE', '대구약령시한의약박물관', '중구', '["체험","관람","문화예술","역사"]', '[1,2,3,4,5,6]', '대구 한방의 역사를 알아보고 다양한 한방 체험을 할 수 있는 공간', 35.868401, 128.589868, NULL, 'https://www.daegu.go.kr/dgom/index.do', 87);
INSERT INTO edumaps_items (id, type, title, category, tags, recommended_grades, description, lat, lng, image_url, external_url, sort) VALUES ('res_199', 'OFFLINE', '한방의료체험타운', '중구', '["체험","관람","문화예술","역사"]', '[1,2,3,4,5,6]', '대구약령시를 알리고 한의학을 쉽게 접할 수 있는 공간', 35.868401, 128.590941, NULL, 'http://kmeditown.go.kr/', 88);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_056', 1, 11, '상상', '내가 음악을 만든다면', '스마트 기기로 나의 상상을 음악으로 표현해 봅시다.', '["나의 상상을 다양한 음악으로 표현해볼까요?"]', '["생활 속 다양한 도구를 활용해 음악을 만들어 봅시다."]', 6);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_071', 4, 4, '사회', '지도로 만나는 우리 지역', '온라인 지도로 우리 동네를 찾아보고 지역의 변화를 비교해 봅시다.', '["옛날 지도와 지금의 디지털 지도를 비교해 보면, 대구 사람들이 모여 사는 곳은 어떻게 변해왔을까요?"]', '["온라인 지도를 캡처한 뒤, 우리 가족만의 ''단골 맛집/놀이터 맞춤형 기호 지도''를 만들어봅시다."]', 34);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_121', 5, 11, '사회', '식민 통치와 저항, 전쟁이 바꾼 사회와 생활', '6.25 전쟁 관련 역사 자료를 관찰하며 전쟁이 우리 사회와 생활에 미친 영향을 파악해 봅시다.', '["6.25 전쟁은 오늘날까지 우리 사회의 모습과 평화 통일의 필요성에 어떤 영향을 주나요?"]', '["전쟁 기념관의 전시물을 분석하고 평화 통일을 위한 실천 목록을 만들어 봅시다."]', 55);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_121', 6, 3, '사회', '평화 통일을 위한 노력', '6.25 전쟁 관련 역사 자료와 전시물을 관찰하며 분단의 아픔과 통일의 필요성을 느껴 봅시다.', '["전쟁은 우리 사회와 사람들의 생활에 어떤 영향을 미쳤을까요?"]', '["[우리 역사넷](https://contents.history.go.kr/front/newEh/list.do?code=eh_age_50)에서 6.25. 전쟁 관련 역사 이야기를 읽고 소감문을 작성해 봅시다."]', 59);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_122', 1, 11, '상상', '우리 반에 공룡이 나타난다면', '공룡이 남긴 다양한 흔적을 찾아봅시다.', '["공룡이 나타난 우리 반을 상상해 볼까요?"]', '["공룡이 나타난 우리 반이나 우리 동네를 그림으로 그려 봅시다.","공룡과 친구가 되려면 어떻게 해야 할 지 이야기 나누어 봅시다."]', 4);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_122', 4, 3, '과학', '지층과 화석', '고산골에 남겨진 공룡 발자국 화석과 지층을 직접 관찰하며 과거의 흔적을 찾아봅시다.', '["이 화석을 남긴 공룡이 살았던 시대의 대구는 어떤 자연환경이었을까요?"]', '["공룡 발자국 화석이 어떤 과정으로 만들어졌을지 설명하는 글을 써봅시다."]', 39);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_122', 5, 3, '과학', '지층과 화석', '고산골에 남겨진 공룡 발자국 화석과 지층을 직접 관찰하며 과거의 흔적을 찾아봅시다.', '["이 화석을 남긴 공룡이 살았던 시대의 대구는 어떤 자연환경이었을까요?"]', '["화석이 만들어지는 과정을 설명하는 글을 쓰거나 중생대 대구의 모습을 상상하여 그려봅시다."]', 46);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_131', 2, 9, '계절', '꼼지락꼼지락', '계절을 느끼며 다양한 자연물로 놀이해 봅시다.', '["어떤 자연물에서 계절의 변화를 느낄 수 있을까요?"]', '["현재 계절에서 볼 수 있는 자연물로 그림을 그려 봅시다.","내가 만져 본 자연물의 특징을 글로 써 봅시다."]', 16);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_131', 3, 7, '과학', '식물의 생활', '다양한 조건의 장소에 있는 여러 가지 식물을 관찰해 봅시다.', '["식물이 사는 환경에 따라 잎이나 줄기의 모양은 왜 서로 다를까요?"]', '["내가 수목원에서 찾은 특이한 식물을 한 가지 골라 모습과 특징을 담은 관찰 보고서를 만들어봅시다."]', 32);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_131', 4, 6, '과학', '다양한 생물과 우리 생활', '수목원의 습지나 숲 속 그늘을 관찰하며 식물 외에도 버섯, 곰팡이 등 다양한 생물이 살고 있음을 탐구해 봅시다.', '["우리 눈에 잘 띄지 않는 균류(버섯, 곰팡이)는 자연환경과 우리 생활에 어떤 이로움과 해로움을 줄까요?"]', '["디지털 현미경이나 스마트폰 확대 카메라로 주변의 다양한 생물을 촬영해 보고, ''다양한 생물 도감''을 만들어봅시다."]', 41);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_131', 5, 11, '과학', '자원과 에너지', '수목원의 다양한 식물을 관찰하며 자연 생태계의 소중함과 자원으로서의 가치를 탐구합시다.', '["식물의 각 기관은 서로 어떻게 연결되어 생명을 유지하며 우리에게 어떤 자원을 주나요?"]', '["식물 사진을 찍어 특징을 설명하는 ''나만의 식물 도감''을 만들어 봅시다."]', 57);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_131', 6, 6, '과학', '식물의 구조와 기능', '수목원의 다양한 식물을 직접 관찰하며 뿌리, 줄기, 잎, 꽃의 생김새와 각각이 하는 일을 조사해 봅시다.', '["식물의 각 기관은 서로 어떻게 연결되어 생명을 유지할까요?"]', '["식물 사진을 찍어 나만의 식물도감을 만들어 봅시다."]', 63);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_132', 2, 11, '물건', '컴퓨터를 잘 다루고 싶어요', '생활을 편리하게 해주는 다양한 컴퓨터와 인공지능 도구에 대해 알아봅시다.', '["컴퓨터로 할 수 있는 것에는 어떤 것들이 있을까요?"]', '["체험관의 여러 시설들을 체험해 보고 신기했던 곳 한 군데를 소개하는 글을 써 봅시다.","내 주변에 있는 어떤 종류의 컴퓨터가 있는지 알아보고 작동 방법을 알아봅시다."]', 20);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_134', 3, 5, '사회', '주변에서 만나는 과거의 모습', '구석기·신석기 유물을 관찰하며 당시 사람들의 도구를 찾아봅시다.', '["옛날 사람들은 주변의 자연물을 어떻게 도구로 활용했을까요?"]', '["내가 관찰한 선사 유물을 주제로 선사 시대를 살아가는 어린이가 되어 상상 일기를 써봅시다."]', 22);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_134', 5, 9, '사회', '유적과 유물로 살펴본 옛 사람들의 생활', '대구 지역의 다양한 선사 시대 유물을 관찰하며 당시 사람들의 생활 모습을 추론해 봅시다.', '["선사 시대의 유물들은 당시 사람들의 사고방식과 생활상을 어떻게 보여주나요?"]', '["관찰한 유물을 바탕으로 선사 시대 사람들의 하루를 상상하여 일기를 써 봅시다."]', 51);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_135', 1, 10, '약속', '수도꼭지를 잠그면, 지구가 뜨끈뜨끈', '우리의 환경을 지키기 위해서 사람들은 어떤 노력을 하고 있나요?', '["우리의 생활과 관련된 지속 가능성의 다양한 사례를 알아볼까요?"]', '["우리 집과 학교에서 실천할 수 있는 환경 보호 약속은 무엇이 있는지 이야기하여 봅시다."]', 3);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_141', 1, 11, '상상', '우리 반에 공룡이 나타난다면', '공룡이 남긴 다양한 흔적을 찾아봅시다.', '["공룡이 나타난 우리 반을 상상해 볼까요?"]', '["공룡이 나타난 우리 반이나 우리 동네를 그림으로 그려 봅시다.","공룡과 친구가 되려면 어떻게 해야 할 지 이야기 나누어 봅시다."]', 5);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_141', 5, 3, '과학', '지층과 화석', '다양한 화석 표본을 관찰하며 지구의 과거 생물과 환경을 추리해 봅시다.', '["화석을 통해 알 수 있는 과거 지구의 비밀은 무엇이며, 화석은 어떤 가치가 있을까요?"]', '["관찰한 화석 중 하나를 골라 그 생물이 살았던 당시 환경을 상상하여 이야기해봅시다."]', 47);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_142', 1, 6, '탐험', '내가 도착한 세상은 어떤 모습일까', '전시관 및 천체투영관 관람을 통해 다양한 세계에 대해 관심을 가져 봅시다.', '["내가 궁금한 세상은 어떻게 표현하면 좋을까요?"]', '["내가 상상한 세상에 대해 그림을 그려 보고 설명하여 봅시다.","또 다른 궁금한 세계를 탐험하기 위해 다양한 매체를 활용하여 봅시다."]', 2);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_142', 2, 10, '인물', '세종대왕과 장영실', '전시관 내 자격루를 살펴보고, 세종대왕이 왜 시계를 만들었을지 생각해 봅시다.', '["우리 생활에 필요한 시계에는 어떤 것이 있을까요?"]', '["주변의 다양한 시계의 모습과 쓰임새를 살펴봅시다.","나만의 시계를 만들어 봅시다."]', 17);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_142', 2, 11, '물건', '발명왕이 되고 싶어요', '사람들을 편하게 해 주는 다양한 물건에 대해 알아봅시다.', '["우리의 생활을 더 편리하게 만들기 위해 어떤 발명이 필요할까요?"]', '["생활 속 불편함을 줄이기 위해 만들어진 발명품 하나를 골라 소개하여 봅시다.","발명 원리를 이용하여 내 주변 물건을 편리하게 발명하기 위한 계획을 세워 봅시다."]', 19);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_142', 3, 12, '사회', '통신수단의 변화로 달라진 생활 모습', '옛날부터 오늘날까지의 통신 기기 변화 과정을 관찰해 봅시다.', '["소식을 전하는 방법이 빨라지면서 우리 삶은 어떻게 달라졌을까요?"]', '["통신 기술의 발달과 관련지어 미래의 통신 기술을 상상해보고, 내가 미래에 사용하고 싶은 새로운 통신 기기를 그려봅시다."]', 25);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_142', 4, 3, '과학', '자석의 이용', '과학관의 자석 체험물을 통해 자석과 철 사이에 작용하는 힘의 특징을 알아보고, 생활 속 활용 사례를 찾아봅시다.', '["보이지 않는 자석의 힘(끌어당기거나 밀어내는 힘)을 이용해 우리 생활을 편리하게 해주는 발명품에는 어떤 원리가 숨어있을까요?"]', '["자석의 성질을 이용한 새로운 발명품 아이디어를 떠올려봅시다."]', 40);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_142', 4, 9, '과학', '밤하늘 관찰', '천체투영관에서 태양계 행성들의 생김새를 관찰하고, 입체적으로 체험해 봅시다.', '["태양계의 여러 행성들은 지구와 어떻게 다를까요?"]', '["태양계 행성을 골라 그 행성을 소개하는 자료를 만들어봅시다."]', 42);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_143', 5, 3, '사회', '우리나라 국토 여행', '낙동강의 지형적 특징과 물, 자연, 문화가 어우러진 건축 예술을 관찰해 봅시다.', '["강 주변의 지형적 특징은 그 지역 사람들의 생활 모습과 여가 활동에 어떤 영향을 줄까요?"]', '["아름다운 국토 사진 공모전을 열거나 가족과 함께하는 지형 탐방 계획을 세워 봅시다."]', 48);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_144', 2, 4, '자연', '숲속 회의에 누가 왔을까', '자연을 지키기 위해 우리는 어떤 노력을 하여야 하는지 알아봅시다.', '["우리의 자연을 왜 보호해야 할까요?"]', '["생명을 소중히 여기기 위한 다짐을 일기로 나타내어 봅시다.","생명을 지키기 위해 내가 집에서 실천할 수 있는 것을 알아보고, 함께 실천해 봅시다."]', 9);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_144', 3, 10, '과학', '지구와 바다', '습지 주변의 지형을 보며 흐르는 물에 의한 지표의 변화를 살펴봅시다.', '["강물은 우리 주변의 땅 모양을 어떻게 깎고 쌓아서 변화시킬까요?"]', '["습지의 중요성과 보존의 필요성을 깨닫고 달성습지를 다양한 방법(카드뉴스, 포스터, 만화 등)으로 홍보해봅시다."]', 33);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_144', 4, 10, '과학', '생물과 환경', '달성습지에 사는 다양한 생물들을 관찰하고, 이들이 서로 어떤 먹고 먹히는 관계를 맺고 있는지 알아봅시다.', '["달성습지의 생태계에서 특정 생물이 갑자기 사라지거나 늘어나면 다른 생물들에게는 어떤 일이 벌어질까요?"]', '["지도 앱을 활용해 달성습지 주변의 환경 변화를 살펴보고, 생태계 보전을 위한 캠페인 포스터를 만들어봅시다."]', 43);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_144', 5, 3, '과학', '우리나라 국토 여행', '습지에 사는 다양한 생물들을 관찰하고 습지 생태계 보전의 중요성을 알아봅시다.', '["습지 생태계에서 특정 생물이 사라지면 다른 생물들에게는 어떤 일이 벌어질까요?"]', '["생태계 보전을 위한 캠페인 포스터를 만들고 학교나 가정에서 공유하여 봅시다."]', 49);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_151', 2, 7, '세계', '이런 옷을 입어요', '다른 나라의 전통 의상을 알아봅시다.', '["다른 나라 사람들은 어떤 옷을 입고 살아갈까요?"]', '["다른 나라 사람들이 왜 그런 전통 의상을 입는지 떠올려봅시다.","다른 나라 사람들이 살고 있는 다양한 집의 모양에 대해서도 알아봅시다."]', 14);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_151', 4, 7, '사회', '경제활동과 지역 간 교류', '과거 대구를 대표했던 섬유 산업의 역사를 알아보고, 대구에서 만든 옷감이 어떻게 다른 지역으로 갔는지 알아봅시다.', '["대구에서 만들어진 섬유(물건)는 어떻게 다른 지역이나 나라로 이동하며, 이 교류는 대구를 어떻게 발전시켰을까요?"]', '["내가 소비하는 물건의 원산지를 확인해 보고, 이 물건이 우리 집까지 온 ''교류 경로 지도''를 그려봅시다."]', 36);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_151', 5, 10, '사회', '달라지는 시대, 변화하는 생활 모습', '대구 섬유 산업의 역사를 통해 경제 성장 과정과 의생활의 변화를 이해해 봅시다.', '["산업화와 경제 성장은 우리 일상생활과 소비 모습에 어떤 변화를 가져왔나요?"]', '["부모님께 산업화 시기의 생활 모습에 대해 인터뷰하고 조사 보고서를 작성해 봅시다."]', 54);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_151', 6, 4, '사회', '경제성장과 산업화', '대구의 주력 산업이었던 섬유 산업의 변천사를 통해 우리나라의 경제 성장 과정을 이해해 봅시다.', '["경제 성장은 우리 일상생활과 소비 모습에 어떤 변화를 가져왔을까요?"]', '["가정에서 부모님이나 조부모님께 산업화 시기(1960~80년대)의 생활 모습에 대해 인터뷰하고, 조사보고서를 작성해 봅시다."]', 60);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_152', 2, 7, '세계', '태풍이 오고 있어요', '전시실을 체험하며 태풍 등 다양한 자연재해에 대해 알아봅시다.', '["태풍이 있는 날에는 어떻게 대비해야 할까요?"]', '["태풍 등 여름철 자연재해에 대해 더 알아봅시다.","자연재해를 예방하는 사람들의 노력에 대해 알아봅시다."]', 15);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_152', 4, 11, '과학', '기후변화와 우리 생활', '기상과학관에서 우리나라의 기후 특징을 알아보고, 태풍 등 다양한 자연재해를 체험해 봅시다.', '["기후변화로 심해지는 자연재해를 줄이기 위해 우리 가족이 당장 할 수 있는 일은 무엇일까요?"]', '["우리 지역의 기후 변화 데이터를 [기상청 누리집](https://climate.go.kr/atlas/dsh/ccf)에서 찾아보고, 뉴스 앵커가 되어 기상 특보 대본을 써봅시다."]', 45);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_152', 5, 10, '과학', '날씨와 우리 생활', '기상 요소와 기상 관측 장비의 원리를 이해하고 날씨가 우리 생활에 주는 영향을 알아봅시다.', '["기상 요소(기온, 바람 등)의 변화는 기후변화 및 자연재해와 어떤 관련이 있을까요?"]', '["우리 지역의 기후 변화 데이터를 [기상청 누리집](https://climate.go.kr/atlas/dsh/ccf)에서 찾아보고, 뉴스 앵커가 되어 기상 특보 대본을 써봅시다."]', 56);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_152', 6, 9, '과학', '계절의 변화', '기상 및 기후 변화 체험을 통해 태양 고도와 기온의 관계를 이해하고 계절이 변하는 원리를 알아봅시다.', '["계절에 따라 태양의 남중 고도와 낮의 길이는 어떻게 달라질까요?"]', '["[어린이 기상교실](https://www.kma.go.kr/kids/)을 활용하여 우리나라의 계절별 날씨 특징을 보고서로 작성합니다."]', 62);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_153', 1, 4, '사람들', '불이 났을 때는', '화재 등 재난상황에 슬기롭게 대처하는 방법을 알아봅시다.', '["불이 났을 때 어떻게 해야 할까요?"]', '["집과 학교에서 불이 났을 때 해야 하는 일을 떠올려 봅시다.","소방관이 하는 일을 알아봅시다."]', 0);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_153', 2, 6, '마을', '자동차를 안전하게', '교통안전 체험에 참여하며 자동차를 안전하게 이용하는 방법을 알아봅시다.', '["자동차를 안전하게 이용하려면 어떻게 해야 할까요?"]', '["대중교통을 이용할 때의 안전 수칙과 예절도 알아봅시다.","생활 속 안전 수칙에 대해 알아봅시다."]', 12);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_154', 2, 4, '자연', '난 네가 궁금해', '전시실을 체험하며 신비한 나비의 세계를 탐구하여 봅시다.', '["관심 있는 나비의 모습과 생김새에 대해 알아볼까요?"]', '["학교와 집 주변에서 볼 수 있는 나비에는 어떤 것이 있는지 더 알아봅시다."]', 8);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_154', 3, 4, '과학', '동물의 생활', '나비의 생김새와 곤충의 구조를 관찰해 봅시다.', '["나비와 같은 곤충들은 어떤 생김새를 가지고 있나요?"]', '["가장 인상 깊었던 곤충을 떠올려보고, 자세히 조사하여 곤충의 몸 구조 세밀화를 그려봅시다."]', 28);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_161', 5, 9, '사회', '역사 전 단원', '우리나라와 대구의 교육 역사, 다양한 문화유산을 통해 과거의 삶을 성찰해 봅시다.', '["과거의 교육 모습과 문화유산은 오늘날 우리의 삶과 정체성에 어떤 의미를 주나요?"]', '["역사관에서 인상 깊었던 유물을 찾아 그 유산에 담긴 가치를 소개하는 뉴스나 신문기사를 제작해 봅시다."]', 52);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_181', 2, 6, '마을', '우리 마을 전시회', '우리 마을에서 볼 수 있는 다양한 전시에 바른 태도로 참여하여 봅시다.', '["우리 마을에서 참여할 수 있는 다양한 전시에는 어떤 것이 있을까요?"]', '["우리 지역의 공연장에서 실시하는 다양한 주제의 공연을 바른 태도로 감상하여 봅시다.","나는 무엇을 전시할지 생각해 보고, 학교 또는 가정에서 작은 전시회를 열어 봅시다."]', 10);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_181', 2, 10, '인물', '시간이 흐르면', '시간의 변화에 따라 달라지는 생활 모습에 대해 관심을 가져 봅시다.', '["시간이 흐름에 따라 우리가 사용하는 물건은 어떻게 달라졌을까요?"]', '["할아버지, 할머니가 쓰셨던 옛날 물건에 대해 대화를 나누어 봅시다.","내가 쓰고 있는 물건이 앞으로 어떻게 달라질지 예상하여 봅시다."]', 18);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_181', 3, 11, '사회', '옛날과 오늘날의 풍습', '전시물 속 조상들의 명절 풍속과 당시의 옷차림을 관찰해 봅시다.', '["옛날부터 전해 내려오는 풍속에는 조상들의 어떤 지혜가 담겨 있을까요?"]', '["새롭게 알게 된 우리 풍습을 되짚어보면서 우리 가족이 지키고 싶은 명절 풍속을 정하고 실천을 약속합시다."]', 26);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_182', 3, 9, '사회', '사회 변화로 달라진 생활 모습', 'ICT 홍보관에서 인공지능, 미래 기술을 직접 체험해 봅시다.', '["과학 기술의 발달은 우리 가족의 삶을 어떻게 변화시킬까요?"]', '["과학 기술의 발달에 따라 미래 지능정보화 시대에 우리 가족을 도와줄 로봇을 설계해 봅시다."]', 24);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_182', 6, 7, '과학', '지구의 운동', '천체관측체험 프로그램이나 과학관의 전시물을 통해 지구의 자전과 공전 원리를 입체적으로 이해해 봅시다.', '["우리가 지구의 움직임을 직접 느끼지 못하는데도 지구가 움직인다는 것을 어떻게 알 수 있을까요?"]', '["지구의 자전과 공전 원리를 조사해 보고서를 작성해 봅시다."]', 64);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_182', 6, 12, '과학', '전기의 이용', '전기 회로를 구성해 보고, 전자석의 성질이 영구 자석과 어떻게 다른지 체험해 봅시다.', '["전자석의 세기와 극을 우리가 마음대로 조절하려면 어떻게 해야 할까요?"]', '["[에듀나비 수업꾸러미](https://www.edunavi.kr/arc/ad/edunavi/arc/cc/selectChnnlCntntsDocLinkInfo.do?chnnlSn=346&cntntsSn=29242&packageSn=1643&isPackage=Y)에서 ''식물의 구조와 기능'' 관련 영상을 살펴봅시다."]', 65);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_182', 5, 4, '사회', '소중한 우리 땅, 독도', '대구창의융합교육원 1층의 독도체험관을 방문하여 독도의 아름다운 자연환경과 역사적 기록을 생생하게 체험해 봅시다.', '["옛날 사람들은 어떤 기록을 통해 독도가 우리 땅임을 남겼을까요? 지금 우리가 일상에서 독도를 알리고 지키기 위해 할 수 있는 일은 무엇일까요?"]', '["에듀테크 도구(미리캔버스, 캔바 등)를 활용하여 ''독도 명예 홍보대사''가 되어 세계 사람들에게 독도를 알리는 디지털 엽서나 카드뉴스를 제작해 봅시다."]', 66);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_183', 1, 4, '사람들', '고마운 사람들', '꿈누리관 사회탐험대 시설을 체험해 보고 우리 주변에서 도움을 주고받는 사람들에 대해 알아봅시다.', '["우리는 누구와 어떤 도움을 주고받으며 살아갈까요?"]', '["나와 많은 사람들이 연결되어 있음을 생각 그림으로 나타내어 봅시다.","고마운 사람에게 감사의 마음을 담은 카드를 만들어 전달하여 봅시다."]', 1);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_183', 2, 6, '마을', '마을 사람들을 만나요', '꿈누리관 사회탐험대 시설을 체험해보고 마을 속에서 만날 수 있는 다양한 사람들에 대해 체험해 봅시다.', '["우리 마을 사람들은 어떤 일을 할까요?"]', '["다양한 마을 구성원의 역할에 대해 더 알아봅시다.","마을 구성원이 되어 역할놀이를 해 봅시다."]', 13);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_184', 2, 4, '자연', '난 네가 궁금해', '전시실 및 곤충생태관을 체험하며 신비한 곤충의 세계를 탐구하여 봅시다.', '["관심 있는 곤충의 모습과 생김새에 대해 알아볼까요?"]', '["학교와 집 주변에서 볼 수 있는 곤충에는 어떤 것이 있는지 더 알아봅시다.","우리에게 이로움을 주는 곤충에 대 더 알아봅시다."]', 7);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_184', 3, 5, '과학', '동물의 생활', '물속 동물과 육상 동물(곤충 등)을 관찰하며 사는 곳에 따른 특징을 비교해 봅시다.', '["동물들이 사는 곳(환경)에 따라 생김새가 다른 이유는 무엇일까요?"]', '["친구(혹은 가족)와 함께 다양한 생태계 속 동물이 되어 서로의 생활에 대해 질문을 주고받는 인터뷰 역할극을 해봅시다."]', 29);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_184', 3, 6, '과학', '식물의 생활', '우리 주변의 식물을 관찰하고 다양한 기준에 따라 분류해 봅시다.', '["식물의 저마다 어떤 다양한 모양과 특징을 가지고 있을까요?"]', '["학교 또는 우리 집 주변의 다양한 식물의 잎을 채집하여 잎 프로타주 활동을 해봅시다."]', 30);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_184', 3, 6, '과학', '생물의 한살이', '씨앗이 싹터서 자라는 과정과 생물의 성장 단계 관찰하기', '["생물이 자라는 과정(알-애벌레-번데기-어른벌레)은 어떻게 다를까요?"]', '["나만의 반려 식물을 정하여 일정한 간격으로 변화를 관찰하며 성장 일기를 써봅시다."]', 31);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_184', 4, 11, '과학', '기후변화와 우리 생활', '녹색환경탐구관에서 기후변화가 우리 환경에 미치는 영향을 확인하고, 이를 줄이기 위한 방법을 체험해 봅시다.', '["기후변화 현상(지구 온난화 등)을 늦추기 위해 우리 가족이 오늘 당장 집에서 실천할 수 있는 행동은 무엇일까요?"]', '["기후 위기로 고통받는 동물의 입장에서 사람들에게 보내는 ''환경 보호 호소문''을 작성해 봅시다."]', 44);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_184', 5, 11, '과학', '자원과 에너지', '기후 위기의 심각성을 체감하고 탄소 중립을 위한 지속 가능한 생활 방법을 체험해 봅시다.', '["기후변화를 늦추기 위해 우리 가족이 오늘 당장 실천할 수 있는 탄소 중립 행동은 무엇일까요?"]', '["기후 위기로 고통받는 동물의 입장에서 사람들에게 보내는 호소문을 작성해 봅시다."]', 58);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_184', 6, 12, '사회', '지속가능한 미래', '대구녹색학습원의 녹색환경탐구관과 자연관찰학습관을 방문하여 기후변화와 생태계 위기의 심각성을 체감해 봅시다.', '["지구촌이 당면한 환경 문제는 우리의 삶과 미래에 어떤 영향을 미칠까요?"]', '["[대구녹색학습원-환경실천 365](https://www.dge.go.kr/dggreen/cm/cntnts/cntntsView.do?mi=2480&cntntsId=5583)에 자신의 체험 후기와 가정에서 실천 중인 환경 보호 활동을 사진과 함께 공유해 봅시다."]', 61);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_191', 2, 6, '마을', '우리 마을 전시회', '우리 마을에서 볼 수 있는 다양한 전시에 바른 태도로 참여하여 봅시다.', '["우리 마을에서 참여할 수 있는 다양한 전시에는 어떤 것이 있을까요?"]', '["우리 지역의 공연장에서 실시하는 다양한 주제의 공연을 바른 태도로 감상하여 봅시다.","나는 무엇을 전시할지 생각해 보고, 학교 또는 가정에서 작은 전시회를 열어 봅시다."]', 11);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_191', 4, 11, '사회', '다양한 환경과 삶의 모습', '과거 연초제조창(담배 공장)이었던 낡은 건물이 예술 공간으로 바뀐 모습을 보며 도시 환경의 변화를 살펴봅시다.', '["낡은 공장을 부수지 않고 새로운 문화 공간으로 바꾸는 것(도시 재생)은 도시 사람들의 삶에 어떤 좋은 점을 줄까요?"]', '["우리 동네의 버려진 공간이나 낡은 건물을 사람들이 즐겨 찾는 멋진 ''미래형 문화 공간''으로 새롭게 디자인해봅시다."]', 38);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_192', 5, 10, '사회', '달라지는 시대, 변화하는 생활 모습', '대구의 근대 역사 전시를 통해 근대 문물 수용 과정과 생활 문화의 변화를 이해해 봅시다.', '["근대 문물의 도입은 당시 대구 사람들의 생활과 생각에 어떤 변화를 가져왔나요?"]', '["근대와 현재의 대구 모습을 비교하는 시간 여행자 가상 그림일기를 써 봅시다."]', 53);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_193', 4, 9, '사회', '민주주의와 자치', '나라의 빚을 갚기 위해 대구 시민들이 스스로 나섰던 기록을 보며, 주민 참여와 자치의 진정한 의미를 알아봅시다.', '["과거 시민들이 스스로 나라의 문제를 해결하려 했던 것처럼, 오늘날 우리가 지역사회를 위해 참여할 수 있는 방법은 무엇일까요?"]', '["우리 동네에서 고쳐야 할 문제점을 찾아 ''우리 동네에서 해결할 10대 과제''를 선정해 봅시다."]', 37);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_193', 5, 6, '사회', '법과 인권의 보장', '국채보상운동 기록을 통해 시민 참여와 권리 보장, 주민 자치의 의미를 알아봅시다.', '["과거 시민들의 자발적 참여 노력은 오늘날 우리 지역 사회 문제 해결에 어떤 교훈을 주나요?"]', '["우리 동네에서 해결이 필요한 문제를 찾아 시청에 편지를 써 봅시다."]', 50);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_194', 3, 3, '과학', '동물의 생활', '달성공원에서 볼 수 있는 다양한 동물을 관찰해 봅시다.', '["동물들은 각각 어떤 생김새를 가지고 어떻게 살아가고 있나요?"]', '["공원에서 만난 여러 가지 동물들의 모습과 특징을 담아 나만의 작은 동물 사전을 만들어 봅시다."]', 27);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_195', 3, 6, '사회', '우리 지역 사람들의 달라진 생활 모습', '1950~60년대 대구의 거리 모습을 보고 오늘날과 비교해 봅시다.', '["시간이 흐르며 우리 고장 사람들의 생활 모습은 어떻게 변했을까요?"]', '["우리 지역의 옛 모습을 떠올리며 70년 전의 대구에 살고 있는 친구에게 편지를 써봅시다."]', 23);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_195', 4, 5, '사회', '우리 지역의 국가유산', '대구의 근대역사 골목과 전시관을 걸으며, 옛날 대구 사람들의 생활 모습과 남겨진 유산의 가치를 알아봅시다.', '["대구 도심 한가운데 남겨진 100년 전의 낡은 건물들은 오늘날 우리에게 어떤 이야기를 들려주고 있을까요?"]', '["옛날 대구 모습을 보여주는 유산을 홍보하는 자료를 만들어봅시다."]', 35);
INSERT INTO edumaps_topics (item_id, grade, month, subject, topic_title, description, inquiry_questions, post_activities, sort) VALUES ('res_196', 3, 4, '사회', '우리 생활에 도움을 주는 장소', '우리 생활에 도움을 주는 상점과 공공기관(은행, 우체국 등)을 관찰해 봅시다.', '["시장은 우리 고장 사람들의 생활에 어떤 도움을 줄까요?"]', '["직접 관찰한 우리 생활에 도움을 주는 장소들로 그림 지도를 만들어봅시다."]', 21);
INSERT INTO edumaps_changelog (date, text, sort) VALUES ('2026.09.14', '기관 명칭을 최신화하였습니다.', 0);
INSERT INTO edumaps_changelog (date, text, sort) VALUES ('2026.07.04', '홈 화면에 다른 사용자가 많이 찾는 자료 바로가기를 추가하였습니다.', 1);
INSERT INTO edumaps_changelog (date, text, sort) VALUES ('2026.06.26', '학년별 로드맵 본문에 관련 자료 링크를 추가하고, 시스템을 안정화하였습니다.', 2);
INSERT INTO edumaps_changelog (date, text, sort) VALUES ('2026.06.01', '검색창 아래 바로가기 아이콘과 추천 자료 홍보 캐러셀이 추가되었습니다.', 3);
INSERT INTO edumaps_changelog (date, text, sort) VALUES ('2026.05.19', '내 근처 필터·지역 필터 시 지도 자동 이동, 로드맵 연계 버튼 개선, 학년 간 전환 기능이 추가되었습니다.', 4);
INSERT INTO edumaps_changelog (date, text, sort) VALUES ('2026.05.08', '온라인 탭 UI 개선 및 학년 표시 통합으로 더 나은 사용 경험을 제공합니다.', 5);
INSERT INTO edumaps_changelog (date, text, sort) VALUES ('2026.05.04', '랜딩페이지에서 학년 미선택 시에도 모든 학년 자료를 표시하도록 개선했습니다.', 6);
INSERT INTO edumaps_changelog (date, text, sort) VALUES ('2026.05.03', '사이트를 처음 만들었습니다.', 7);
